"""Build a self-contained offline AC result viewer from validated source tables."""
from pathlib import Path
import json
import pandas as pd

HERE=Path(__file__).resolve().parent
def records(path,columns):
    d=pd.read_csv(path,low_memory=False);d=d[[c for c in columns if c in d]]
    return d.astype(object).where(pd.notna(d),None).to_dict('records')
def main():
    summary_columns=['analysis_cohort','version','scope','condition','support','n','m','class_pair','direction',
      'registered_physical_pairs','registered_images','registered_buildings','registered_unique_teams',
      'common_Q_physical_pairs','common_Q_unique_teams','images','buildings','image_equal_mean','image_median',
      'cluster_bootstrap_low','cluster_bootstrap_high','building_equal_mean','positive_images','negative_images',
      'up_gt_1p0_images','down_lt_minus_1p0_images','within_pm_1p0_images','abs_dQ_image_equal_mean','support_tier']
    image_columns=['image','building','dQ','abs_dQ','Q_A','Q_C','physical_pairs','target_pools','official_difficulty',
      'structural_condition','room_type','analysis_cohort','version','scope','condition','n','m','class_pair','support']
    strata_columns=['analysis_cohort','version','scope','condition','n','m','class_pair','stratum_type','stratum','direction',
      'physical_pairs','images','buildings','image_equal_mean','mean_absolute_pair_effect_image_equal','positive_images',
      'negative_images','within_pm_1p0_images','up_gt_1p0_images','down_lt_minus_1p0_images']
    payload=dict(summary=records(HERE/'analysis/SIX_DIRECTION_Q_BY_BUDGET.csv',summary_columns),
      images=records(HERE/'analysis/MAIN_IMAGE_EFFECTS.csv.gz',image_columns),
      strata=records(HERE/'analysis/CONDITION_STRATIFIED_Q.csv',strata_columns))
    data=json.dumps(payload,ensure_ascii=False,separators=(',',':'),allow_nan=False).replace('</','<\\/')
    html=HTML.replace('__DATA__',data)
    out=HERE/'workbench';out.mkdir(exist_ok=True);(out/'index.html').write_text(html,encoding='utf-8')
    (out/'BUILD_RECEIPT.json').write_text(json.dumps(dict(summary_rows=len(payload['summary']),image_rows=len(payload['images']),strata_rows=len(payload['strata']),embedded_data=True,network_required=False),indent=2))
    print(json.dumps(dict(html_bytes=len(html.encode()),**json.loads((out/'BUILD_RECEIPT.json').read_text()))))

